def divis13(n):
    s=0
    sg=-1
    while len(n)>=3:
        v = int(n[len(n)-3:len(n)])
        s = s+v*sg
        sg=-sg
        n=n[:len(n)-3]
    if n!='':
        v = int(n)
        s = s+v*sg
    return abs(s)%13 == 0

def remplir2(F1,F2,F3,nb):
