def som(ch):
    sg=1
    s=0
    j=0
    for i in range(len(ch)-1,-1,-1):
        x = int(ch[i]) ; j=j+1
        if j==1:
            s=s+x*1*sg
        elif j==2 :
            s=s+x*3*sg
        else:
            s=s+x*2*sg
        if j==3:
            sg=-sg
            j=0
    return s

def divis7(ch):
    s=0
    while len(ch)>=2:
        s=s+som(ch)
        ch=str(s)
    return s==0 or s==7
